-- Schéma des corrélatifs en HTML, interactif, à la place de l'image korelativoj.svg (#1110) :
-- section 5.2 du Cours en 10 leçons (« Les corrélatifs »), marqueur ##KORELATIVOJ:{json}## rendu par webui.inc.php.
-- Rejouable : ne touche que le contenu qui a encore l'image.
SET NAMES utf8mb4;
UPDATE lecioneroj le
JOIN lecionoj l ON l.id = le.leciono_id
SET le.enhavo = REPLACE(le.enhavo,
  '<div class="skemo-rulumebla"><img src="fr/cge/bildoj/korelativoj.svg" class="responsive-img" alt="Schéma des corrélatifs, à gauche nous avons la liste des 5 préfixes : KI/TI/I/ĈI/NENI et à droite la liste des 9 suffixes : O/A/U/ES/OM/AM/AL/EL/E. En combinant un préfixe et un suffixe, on peut former 45 corrélatifs différents"></div>\n\t\t<p class="hide-on-med-and-up center-align"><small>(faites défiler le schéma vers la droite)</small></p>',
  '##KORELATIVOJ:{"komencoj": [["ki", "interrogatif"], ["ti", "démonstratif"], ["i", "indéfini"], ["ĉi", "totalité"], ["neni", "négatif"]], "finoj": [["o", "chose"], ["u", "individu"], ["a", "qualité"], ["e", "lieu"], ["am", "temps"], ["el", "manière"], ["al", "cause"], ["om", "quantité"], ["es", "possession"]], "ekzemplo": ["ki", "al"], "vortoj": {"kio": "que, quoi", "kiu": "qui, quel(le), lequel", "kia": "quelle sorte de", "kie": "où", "kiam": "quand", "kiel": "comment, comme", "kial": "pourquoi", "kiom": "combien", "kies": "de qui, à qui, dont", "tio": "cela", "tiu": "ce, celui-là, celle-là", "tia": "tel, telle, cette sorte de", "tie": "là, là-bas", "tiam": "alors", "tiel": "ainsi", "tial": "c’est pourquoi, pour cette raison", "tiom": "tant, autant", "ties": "de celui-là", "io": "quelque chose", "iu": "quelqu’un, un(e) certain(e)", "ia": "une sorte de", "ie": "quelque part", "iam": "un jour", "iel": "d’une certaine manière", "ial": "pour une certaine raison", "iom": "un peu", "ies": "de quelqu’un", "ĉio": "tout", "ĉiu": "chacun(e), chaque", "ĉia": "toute sorte de", "ĉie": "partout", "ĉiam": "toujours", "ĉiel": "de toute manière", "ĉial": "pour toute raison", "ĉiom": "le tout", "ĉies": "de tous", "nenio": "rien", "neniu": "personne, nul, aucun", "nenia": "aucune sorte de", "nenie": "nulle part", "neniam": "jamais", "neniel": "d’aucune manière", "nenial": "pour aucune raison", "neniom": "rien du tout, aucune quantité", "nenies": "de personne"}}##')
WHERE l.kurso = 'CG' AND l.numero = 5 AND le.ordo = 2 AND le.enhavo LIKE '%korelativoj.svg%';
